def keys(d, p=""):
    return {k2 for k, v in d.items() for k2 in (keys(v, p + k + ".") if isinstance(v, dict) else {p + k})}


assert keys(vi) == keys(en), keys(vi) ^ keys(en)
for loc, d in (("vi", vi), ("en", en)):
    with open(f"apps/web/messages/{loc}/customers.json", "w", encoding="utf-8") as f:
        json.dump(d, f, ensure_ascii=False, indent=2)
        f.write("\n")
print("ok", len(keys(vi)))
